export interface Transition<S extends string, E extends string> {
  target: S;
  guard?: (context: Record<string, unknown>) => boolean;
  actions?: Array<(context: Record<string, unknown>) => void>;
}

export interface StateConfig<S extends string, E extends string> {
  transitions?: Partial<Record<E, Transition<S, E>>>;
  onEnter?: (context: Record<string, unknown>) => void;
  onExit?: (context: Record<string, unknown>) => void;
}

export class StateMachine<S extends string, E extends string> {
  private states: Partial<Record<S, StateConfig<S, E>>>;
  private current: S;
  private context: Record<string, unknown>;
  private history: S[];

  constructor(
    states: Partial<Record<S, StateConfig<S, E>>>,
    initial: S,
    context: Record<string, unknown> = {}
  ) {
    this.states = states;
    this.current = initial;
    this.context = context;
    this.history = [initial];
  }

  /** Get current state. */
  getState(): S {
    return this.current;
  }

  /** Get current context. */
  getContext(): Record<string, unknown> {
    return { ...this.context };
  }

  /** Send event, triggering transition if defined and guard passes. */
  send(event: E): boolean {
    // TODO
    return false;
  }

  /** Get the full history of visited states. */
  getHistory(): S[] {
    return [...this.history];
  }

  /** Check if state was ever visited. */
  wasVisited(state: S): boolean {
    return this.history.includes(state);
  }
}

