import { StateMachine } from './machine';

type TrafficState = 'red' | 'green' | 'yellow';
type TrafficEvent = 'GO' | 'SLOW' | 'STOP';

function buildTrafficLight() {
  return new StateMachine<TrafficState, TrafficEvent>({
    red: { transitions: { GO: { target: 'green' } } },
    green: { transitions: { SLOW: { target: 'yellow' } } },
    yellow: { transitions: { STOP: { target: 'red' } } },
  }, 'red');
}

test('initial state', () => {
  const sm = buildTrafficLight();
  expect(sm.getState()).toBe('red');
});

test('basic transition', () => {
  const sm = buildTrafficLight();
  expect(sm.send('GO')).toBe(true);
  expect(sm.getState()).toBe('green');
});

test('unknown event returns false', () => {
  const sm = buildTrafficLight();
  expect(sm.send('SLOW')).toBe(false); // not valid from red
  expect(sm.getState()).toBe('red');
});

test('actions executed on transition', () => {
  const log: string[] = [];
  const sm = new StateMachine<'a' | 'b', 'GO'>({
    a: { transitions: { GO: { target: 'b', actions: [() => log.push('action!')] } } },
    b: {},
  }, 'a');
  sm.send('GO');
  expect(log).toEqual(['action!']);
});

test('guard prevents transition', () => {
  const sm = new StateMachine<'locked' | 'open', 'UNLOCK'>({
    locked: { transitions: { UNLOCK: { target: 'open', guard: (ctx) => ctx.hasKey === true } } },
    open: {},
  }, 'locked', { hasKey: false });
  expect(sm.send('UNLOCK')).toBe(false);
  expect(sm.getState()).toBe('locked');
});

test('guard allows transition when condition met', () => {
  const sm = new StateMachine<'locked' | 'open', 'UNLOCK'>({
    locked: { transitions: { UNLOCK: { target: 'open', guard: (ctx) => ctx.hasKey === true } } },
    open: {},
  }, 'locked', { hasKey: true });
  expect(sm.send('UNLOCK')).toBe(true);
  expect(sm.getState()).toBe('open');
});

test('history tracks visited states', () => {
  const sm = buildTrafficLight();
  sm.send('GO');
  sm.send('SLOW');
  sm.send('STOP');
  const history = sm.getHistory();
  expect(history).toEqual(['red', 'green', 'yellow', 'red']);
});

test('wasVisited', () => {
  const sm = buildTrafficLight();
  expect(sm.wasVisited('red')).toBe(true);
  expect(sm.wasVisited('green')).toBe(false);
  sm.send('GO');
  expect(sm.wasVisited('green')).toBe(true);
});
